package com.opspilot.document; import java.util.*; import com.opspilot.document.dto.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController public class DocumentController{private final DocumentService s;public DocumentController(DocumentService s){this.s=s;}private Long u(Authentication a){return(Long)a.getPrincipal();}@PostMapping("/api/workspaces/{workspaceId}/documents") public ResponseEntity<DocumentResponse> create(Authentication a,@PathVariable Long workspaceId,@Valid @RequestBody CreateDocumentRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(workspaceId,u(a),r));}@GetMapping("/api/workspaces/{workspaceId}/documents") public List<DocumentSummaryResponse> list(Authentication a,@PathVariable Long workspaceId,@RequestParam(defaultValue="ACTIVE") DocumentStatus status){return s.list(workspaceId,u(a),status);}@GetMapping("/api/documents/{documentId}") public DocumentResponse get(Authentication a,@PathVariable Long documentId){return s.get(documentId,u(a));}@PatchMapping("/api/documents/{documentId}") public DocumentResponse update(Authentication a,@PathVariable Long documentId,@Valid @RequestBody UpdateDocumentRequest r){return s.update(documentId,u(a),r);}@PostMapping("/api/documents/{documentId}/archive") public DocumentResponse archive(Authentication a,@PathVariable Long documentId){return s.archive(documentId,u(a));}}
